INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'explore', 'v.', '/ɪkˈsplɔː/', '探索;勘探', 'Travellers explore unusual and remote destinations.', '旅行者会探索一些不寻常的偏远目的地。', 'On the Road', 46, 0, 'senior', 'wordlist', 'required2', 'U5', 'explore a place', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'kangaroo', 'n.', '/ˌkæŋɡəˈruː/', '袋鼠', 'She enjoys photographing animals such as dolphins and kangaroos.', '她喜欢拍摄海豚和袋鼠等动物。', 'On the Road', 47, 0, 'senior', 'wordlist', 'required2', 'U5', 'a wild kangaroo', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'crocodile', 'n.', '/ˈkrɒkədaɪl/', '鳄鱼', 'She once photographed a crocodile swimming close to the boat.', '她曾拍下一条游近船边的鳄鱼。', 'On the Road', 48, 0, 'senior', 'wordlist', 'required2', 'U5', 'a wild crocodile', NULL, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('f2u5.01', '①前置 -ing(单个分词作定语:a running river)', 'A2', 10, '外研社版必修第二册 U5 — 单个 -ing 分词放在名词前作定语,表主动/正在进行(被修饰名词主动发出该动作):the rising sun = 正在升起的太阳。干扰的 -ed 表被动/完成,在此不成立。', 1, 'required2', 'U5', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('f2u5.02', '②后置 -ing 短语(= 定语从句:the road leading to town)', 'A2', 10, '外研社版必修第二册 U5 — -ing 分词带宾语/状语时放在名词后作定语,相当于一个主动的定语从句(the road leading to town = the road that leads to town)。', 2, 'required2', 'U5', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('f2u5.03', '③-ing 与 -ed 作定语的主动/被动对比', 'A2', 10, '外研社版必修第二册 U5 — 事物使人产生感受时,用 -ing(主动:令人……的);人感到该感受时才用 -ed。an exciting journey = 令人兴奋的旅程(旅程主动让人兴奋)。', 3, 'required2', 'U5', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U5' AND code='f2u5.01'), 'Look at the ____ sun over the eastern hills; it is going to be a fine day.', 'rising', 'risen', 'to rise', 'rise', 'A', '太阳主动''正在升起'',名词前用 -ing;risen 表完成/被动,在此不成立。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U5' AND code='f2u5.01'), 'Cars cannot cross the ____ river after two days of heavy rain.', 'flowed', 'flowing', 'to flow', 'flow', 'B', '河水主动奔流,前置定语用 flowing。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U5' AND code='f2u5.01'), 'We filled our bottles with cold ____ water from the mountain spring.', 'ran', 'to run', 'running', 'run', 'C', 'running water 流动的水,水主动流动,用 -ing。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U5' AND code='f2u5.01'), 'The ____ road up the hill made our drive into the village very slow.', 'wound', 'to wind', 'wind', 'winding', 'D', '蜿蜒的路,路主动''盘绕而上'',用 winding;wound 表被动不成立。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U5' AND code='f2u5.01'), 'We stopped the car to watch the ____ sun turn the sky orange.', 'setting', 'set', 'to set', 'sets', 'A', '正在西沉的太阳,主动进行,用 setting。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U5' AND code='f2u5.01'), 'A ____ number of tourists visit this small island every summer.', 'grown', 'growing', 'to grow', 'grow', 'B', 'a growing number 不断增长的数量,主动进行,用 -ing。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U5' AND code='f2u5.01'), 'The ____ wind on the mountain pass made every traveller shiver.', 'frozen', 'to freeze', 'freezing', 'freeze', 'C', '刺骨的(正在使人冷的)风,主动用 freezing;frozen 表被冻结,在此不成立。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U5' AND code='f2u5.01'), 'We could hear ____ dogs as we walked through the quiet village at night.', 'barked', 'to bark', 'bark', 'barking', 'D', '正在吠叫的狗,主动进行,用 barking。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U5' AND code='f2u5.01'), 'The ____ holiday gave us a perfect chance to plan a long trip.', 'coming', 'come', 'to come', 'comes', 'A', '即将到来的假期,主动用 coming(= the holiday that is coming)。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U5' AND code='f2u5.01'), 'The ____ seasons make this region beautiful all year round.', 'changed', 'changing', 'to change', 'change', 'B', '不断变化的季节,主动进行,用 changing;changed 表被改变,不合此意。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U5' AND code='f2u5.01'), 'From the boat we watched the ____ stars above the calm dark sea.', 'shone', 'to shine', 'shining', 'shine', 'C', '闪耀的星星,星星主动发光,用 shining。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U5' AND code='f2u5.01'), 'The ____ storm forced the travellers to stay one more night at the inn.', 'approached', 'to approach', 'approach', 'approaching', 'D', '正在逼近的风暴,主动进行,用 approaching。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U5' AND code='f2u5.01'), 'A ____ passenger missed his stop and only woke up at the last station.', 'sleeping', 'slept', 'to sleep', 'sleep', 'A', '正在睡觉的乘客,主动进行,用 sleeping。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U5' AND code='f2u5.01'), 'The ____ passengers on the platform kept looking at their watches.', 'waited', 'waiting', 'to wait', 'wait', 'B', '正在等候的乘客,主动进行,用 waiting。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U5' AND code='f2u5.01'), 'The ____ train left the station exactly on time this morning.', 'departed', 'to depart', 'departing', 'depart', 'C', '正要离站的列车,主动用 departing。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U5' AND code='f2u5.01'), 'The ____ hills around the lake were covered with thick green trees.', 'surrounded', 'to surround', 'surround', 'surrounding', 'D', '周围的群山,山主动''环绕'',用 surrounding;hills 本身不被环绕,故不用 surrounded。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U5' AND code='f2u5.01'), 'We waved at the ____ cars from the side of the country road.', 'passing', 'passed', 'to pass', 'pass', 'A', '经过的车,车主动驶过,用 passing。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U5' AND code='f2u5.01'), 'We could hear the ____ waves against the rocks all through the night.', 'rolled', 'rolling', 'to roll', 'roll', 'B', '翻滚的海浪,主动进行,用 rolling。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U5' AND code='f2u5.01'), 'The ____ engine of the old tour bus made a very loud noise.', 'roared', 'to roar', 'roaring', 'roar', 'C', '轰鸣的引擎,主动发声,用 roaring。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U5' AND code='f2u5.01'), 'Bright ____ lights welcomed us to the small seaside town at night.', 'flashed', 'to flash', 'flash', 'flashing', 'D', '闪烁的灯,主动闪烁,用 flashing。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U5' AND code='f2u5.02'), 'The road ____ to the village is very steep and narrow.', 'leading', 'led', 'to lead', 'lead', 'A', '= the road that leads to the village,主动后置定语用 leading。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U5' AND code='f2u5.02'), 'The man ____ next to the driver is our local guide for the trip.', 'sat', 'sitting', 'to sit', 'sit', 'B', '= the man who is sitting next to the driver,主动后置用 sitting。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U5' AND code='f2u5.02'), 'The train ____ from Beijing arrives at the coast around noon.', 'come', 'to come', 'coming', 'comes', 'C', '= the train that comes from Beijing,主动用 coming。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U5' AND code='f2u5.02'), 'Tourists ____ photos of the blue lake were smiling happily.', 'taken', 'to take', 'take', 'taking', 'D', '= tourists who were taking photos,主动用 taking;taken 表被动不成立。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U5' AND code='f2u5.02'), 'The bus ____ along the coast offers wonderful views of the sea.', 'running', 'ran', 'to run', 'run', 'A', '= the bus that runs along the coast,主动用 running。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U5' AND code='f2u5.02'), 'The river ____ through the green valley is deep and very cold.', 'flowed', 'flowing', 'to flow', 'flow', 'B', '= the river that flows through the valley,主动用 flowing。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U5' AND code='f2u5.02'), 'The plane ____ to London was delayed for hours by the storm.', 'flown', 'to fly', 'flying', 'fly', 'C', '= the plane that was flying to London,主动用 flying;flown 表被动不成立。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U5' AND code='f2u5.02'), 'The path ____ up the hill is hard to follow when it rains.', 'wound', 'to wind', 'wind', 'winding', 'D', '= the path that winds up the hill,主动用 winding。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U5' AND code='f2u5.02'), 'A sign ____ the way to the museum stood at the street corner.', 'showing', 'shown', 'to show', 'show', 'A', '= a sign that showed the way,主动用 showing;shown 表被动不成立。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U5' AND code='f2u5.02'), 'The guide ____ in front of us spoke loudly and very clearly.', 'walked', 'walking', 'to walk', 'walk', 'B', '= the guide who was walking in front,主动用 walking。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U5' AND code='f2u5.02'), 'The family ____ in the car behind us were singing travel songs.', 'travelled', 'to travel', 'travelling', 'travel', 'C', '= the family who were travelling in the car,主动用 travelling。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U5' AND code='f2u5.02'), 'A couple ____ their heavy luggage hurried past the boarding gate.', 'carried', 'to carry', 'carry', 'carrying', 'D', '= a couple who were carrying their luggage,主动用 carrying。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U5' AND code='f2u5.02'), 'The children ____ on the beach built tall castles out of sand.', 'playing', 'played', 'to play', 'play', 'A', '= the children who were playing on the beach,主动用 playing。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U5' AND code='f2u5.02'), 'The ferry ____ the wide river was completely full of cars.', 'crossed', 'crossing', 'to cross', 'cross', 'B', '= the ferry that was crossing the river,主动用 crossing。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U5' AND code='f2u5.02'), 'The woman ____ the paper map gave us very clear directions.', 'held', 'to hold', 'holding', 'hold', 'C', '= the woman who was holding the map,主动用 holding。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U5' AND code='f2u5.02'), 'The boat ____ near the shore was full of happy young tourists.', 'sailed', 'to sail', 'sail', 'sailing', 'D', '= the boat that was sailing near the shore,主动用 sailing。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U5' AND code='f2u5.02'), 'People ____ aboard the ship waved goodbye to their families.', 'going', 'gone', 'to go', 'goes', 'A', '= people who were going aboard,主动用 going;gone 表被动/完成不成立。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U5' AND code='f2u5.02'), 'The travellers ____ for the late bus grew more and more impatient.', 'waited', 'waiting', 'to wait', 'wait', 'B', '= the travellers who were waiting for the bus,主动用 waiting。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U5' AND code='f2u5.02'), 'The lights ____ in the distance showed us the way back to town.', 'shone', 'to shine', 'shining', 'shine', 'C', '= the lights that were shining in the distance,主动用 shining。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U5' AND code='f2u5.02'), 'A young man ____ a large backpack asked us the way to the station.', 'worn', 'to wear', 'wear', 'wearing', 'D', '= a young man who was wearing a backpack,主动用 wearing;worn 表被动不成立。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U5' AND code='f2u5.03'), 'It was the most ____ journey of my whole life, full of surprises.', 'exciting', 'excited', 'to excite', 'excite', 'A', '旅程令人兴奋,事物用 -ing;若说人 excited 才用 -ed。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U5' AND code='f2u5.03'), 'We enjoyed an ____ view of the whole bay from the mountain top.', 'amazed', 'amazing', 'to amaze', 'amaze', 'B', '景色令人惊叹,事物主动''使人惊叹'',用 amazing。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U5' AND code='f2u5.03'), 'The night bus to the coast turned out to be a really ____ ride.', 'tired', 'to tire', 'tiring', 'tire', 'C', '车程令人疲惫,事物用 tiring;人累才说 tired。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U5' AND code='f2u5.03'), 'Our guide told us an ____ story about the old fishing harbour.', 'interested', 'to interest', 'interest', 'interesting', 'D', '故事有趣,事物用 interesting;人感兴趣才说 interested。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U5' AND code='f2u5.03'), 'A long ____ delay at the airport ruined the whole morning for us.', 'annoying', 'annoyed', 'to annoy', 'annoy', 'A', '延误令人恼火,事物用 annoying。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U5' AND code='f2u5.03'), 'The ____ news about the cancelled flight upset everyone at the gate.', 'disappointed', 'disappointing', 'to disappoint', 'disappoint', 'B', '消息令人失望,事物用 disappointing。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U5' AND code='f2u5.03'), 'We had a ____ experience while crossing the wild empty desert.', 'frightened', 'to frighten', 'frightening', 'frighten', 'C', '经历令人害怕,事物用 frightening。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U5' AND code='f2u5.03'), 'From the cliff we saw a truly ____ sight as the sun went down.', 'surprised', 'to surprise', 'surprise', 'surprising', 'D', '景象令人惊讶,事物用 surprising。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U5' AND code='f2u5.03'), 'The ____ scenery along the coast made us stop the car several times.', 'charming', 'charmed', 'to charm', 'charm', 'A', '风景迷人,事物主动''使人着迷'',用 charming。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U5' AND code='f2u5.03'), 'Reaching the top after the long climb was a ____ moment for us all.', 'satisfied', 'satisfying', 'to satisfy', 'satisfy', 'B', '时刻令人满足,事物用 satisfying。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U5' AND code='f2u5.03'), 'We were given a ____ map that led us the wrong way twice.', 'confused', 'to confuse', 'confusing', 'confuse', 'C', '地图令人困惑,事物用 confusing;人糊涂才说 confused。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U5' AND code='f2u5.03'), 'The slow local train ride soon became a ____ part of the day.', 'bored', 'to bore', 'bore', 'boring', 'D', '车程令人无聊,事物用 boring;人感到无聊才说 bored。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U5' AND code='f2u5.03'), 'The sudden storm at sea was a ____ event for the small crew.', 'shocking', 'shocked', 'to shock', 'shock', 'A', '事件令人震惊,事物用 shocking。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U5' AND code='f2u5.03'), 'The poor road signs were a ____ problem for every driver there.', 'worried', 'worrying', 'to worry', 'worry', 'B', '问题令人担忧,事物用 worrying;人担心才说 worried。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U5' AND code='f2u5.03'), 'In the end, a safe and happy journey home was a ____ result.', 'pleased', 'to please', 'pleasing', 'please', 'C', '结果令人高兴,事物用 pleasing。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U5' AND code='f2u5.03'), 'The poster on the wall showed an ____ photo of a wild waterfall.', 'inspired', 'to inspire', 'inspire', 'inspiring', 'D', '照片鼓舞人心,事物用 inspiring。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U5' AND code='f2u5.03'), 'Climbing the volcano turned out to be an ____ task for the group.', 'exhausting', 'exhausted', 'to exhaust', 'exhaust', 'A', '任务使人精疲力竭,事物用 exhausting;人累垮才说 exhausted。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U5' AND code='f2u5.03'), 'The old town was a ____ maze of narrow little streets and steps.', 'puzzled', 'puzzling', 'to puzzle', 'puzzle', 'B', '迷宫令人费解,事物用 puzzling。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U5' AND code='f2u5.03'), 'The cool sea breeze gave us a ____ feeling after the long hot drive.', 'refreshed', 'to refresh', 'refreshing', 'refresh', 'C', '感觉清爽提神,事物用 refreshing。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U5' AND code='f2u5.03'), 'The colourful street festival was an ____ event for all the visitors.', 'excited', 'to excite', 'excite', 'exciting', 'D', '活动令人兴奋,事物用 exciting。', 2, 20, 'mcq');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'From Chef to Travel Blogger', 'Lauren Bath once worked as a chef, and she was happy enough in the kitchen. Yet she wanted more from life: above all, she wanted to travel. Around that time she discovered blogging and noticed that her photographs were rather good, so she began posting them online. Within eighteen months, more than two hundred thousand people were reading her blog. At first it was only a hobby, but soon companies started paying her to take pictures for them. In 2013 she made a brave choice. She quit her job and set out to become her country''s first professional travel photo blogger. It was a hard road, but she managed it. Now she spends about three weeks of every month on the move, and hundreds of thousands of fans follow her journeys online. Through her camera, she has come to understand her own country and its people far better than ever before.', '记叙·旅行摄影博主 Lauren 的转行故事', 151, '[{"q":"What is the passage mainly about?","answer":"A","options":["How a hobby slowly grew into Lauren''s full-time career.","How to take better photographs while cooking.","Why being a chef is harder than travelling.","How blogs make every traveller rich and famous."],"explanation":"全文讲她由业余爱好走向职业博主的过程,选概括项;其余与文意不符。"},{"q":"Why did companies begin to pay Lauren?","answer":"B","options":["She had trained for years as a photographer.","Her pictures were good enough for them to use.","She offered to work for them without pay.","She owned a famous travel company."],"explanation":"原文说她照片很好,公司开始付费请她拍照,选转述项。"},{"q":"How does Lauren spend most of her time now?","answer":"A","options":["She travels for much of each month and shares it online.","She works quietly in a kitchen every day.","She stays at home writing about cooking.","She teaches photography in a single city."],"explanation":"末段说她每月大部分时间在路上并在线分享,选转述项。"}]'::jsonb, '[{"word":"blogger","cn":"博主"},{"word":"profession","cn":"职业"},{"word":"quit","cn":"辞去"}]'::jsonb, 2, 'required2', 'U5', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'A Train Through the Mountains', 'The Bernina Express is one of the most famous train journeys in Europe. It follows a route running from the eastern part of Switzerland down into the north of Italy. People travelling aboard the train have the chance to see scenery that few roads can reach. The landscape lining the route is both beautiful and dramatic, with snowy mountains rising on one side and green valleys opening on the other. Tunnels and high bridges carry the train across deep rivers and around steep hills. For many passengers, the journey itself matters far more than the destination. There is no hurry at all; the train moves slowly on purpose, so that travellers can enjoy every single view. As one writer once put it, the window becomes a kind of television screen, and the natural world outside is the show. If you long to get back to nature without ever leaving your seat, this slow and gentle ride is very hard to beat.', '说明·Bernina Express 观光列车', 161, '[{"q":"Where does the Bernina Express route run?","answer":"B","options":["From the south of Italy back to France.","From the east of Switzerland to the north of Italy.","Around a single Swiss city only.","Across the whole continent of Europe."],"explanation":"原文说路线从瑞士东部通往意大利北部,选转述项。"},{"q":"Why do many passengers enjoy this train?","answer":"C","options":["It is the cheapest way to reach Italy.","It reaches the destination faster than any road.","They care more about the views than about arriving fast.","It allows them to drive their own cars."],"explanation":"原文说对许多乘客而言旅程本身比目的地更重要、慢行赏景,选转述项。"},{"q":"What does the writer compare the train window to?","answer":"D","options":["A map of the whole route.","A photograph on the wall.","A door leading to the city.","A television screen showing the natural world."],"explanation":"原文把车窗比作电视屏幕、窗外自然界是节目,选对应项。"}]'::jsonb, '[{"word":"route","cn":"路线"},{"word":"aboard","cn":"在(车上)"},{"word":"landscape","cn":"风景"}]'::jsonb, 2, 'required2', 'U5', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'Coast to Coast by Motor Home', 'Eva and her family crossed North America from western to eastern Canada in just two weeks. They began in Vancouver, where they picked up a motor home, a house on wheels that took them wherever and whenever they wished. Her father did all the driving, though he had a poor sense of direction, and the family got lost more than once even with the help of GPS. Still, in the end they crossed the Rocky Mountains safely. Eva had hoped to spot a bear or an eagle, but all she saw was a small group of deer. The views, however, were unforgettable: thick forests, snowy peaks and great masses of ice. By the eighth day they reached Quebec, where most people speak a kind of Canadian French. Their long journey finally ended in Newfoundland, the far eastern edge of the country. There, on a boat trip, they were lucky enough to watch a killer whale leap from the cold grey water.', '记叙·一家人房车横穿加拿大', 161, '[{"q":"How did the family travel across Canada?","answer":"A","options":["In a motor home that they drove themselves.","By a fast train from coast to coast.","On a series of long flights.","On bikes along the coast road."],"explanation":"原文说他们取了一辆房车自驾,选转述项。"},{"q":"What did Eva actually see in the Rocky Mountains?","answer":"B","options":["Several bears and a large eagle.","Only a few deer, not the bears she had wished for.","Nothing but ice and empty roads.","A whale swimming in a river."],"explanation":"原文说她想看熊或鹰,结果只看到一小群鹿,选转述项。"},{"q":"Where did their journey come to an end?","answer":"C","options":["Back in Vancouver, where they had started.","In the middle of the Rocky Mountains.","In Newfoundland, at the eastern edge of Canada.","In a French town in Europe."],"explanation":"原文说旅程在加拿大最东端的纽芬兰结束,选转述项。"}]'::jsonb, '[{"word":"vehicle","cn":"交通工具"},{"word":"continent","cn":"大陆"},{"word":"deer","cn":"鹿"}]'::jsonb, 2, 'required2', 'U5', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'Getting Ready for a Trip', 'Planning a trip carefully can save a traveller a great deal of trouble. Before Andrew and Matt set off for Jakarta, they shared the work between them. First they chose their destination and did some research online. Andrew checked the embassy website and found that they did not need to apply for a visa in advance; they could simply get one at the airport instead. He also booked accommodation that fit the budget they had agreed on, choosing a hotel chain that was clean, central and cheap. Matt, meanwhile, bought the plane tickets and arranged the transfer from the airport to their hotel. There were still a few small tasks left to do. They had to check in online, print their boarding passes and pack their luggage. Matt also reminded Andrew to exchange some foreign currency, since he planned to pay for souvenirs in cash rather than by card. With everything ready at last, the two friends could hardly wait to leave.', '说明·两位朋友的出行准备', 162, '[{"q":"Why did the two friends not need a visa in advance?","answer":"D","options":["They were not leaving their own country.","Their hotel arranged the visa for them.","Visas were no longer required anywhere.","They could get one after they landed."],"explanation":"原文说他们可在机场办签证,选转述项。"},{"q":"What did Matt mainly take care of?","answer":"A","options":["Buying the tickets and arranging the airport pickup.","Booking the hotel and checking the visa rules.","Packing all of the luggage for both of them.","Exchanging the money at the embassy."],"explanation":"原文说 Matt 买机票并安排接送,选转述项。"},{"q":"Why did Matt want some foreign cash?","answer":"B","options":["He did not trust the hotel chain.","He meant to buy souvenirs without using a card.","He had lost his credit card already.","Cash was the only way to book flights."],"explanation":"原文说他想用现金而非刷卡买纪念品,选转述项。"}]'::jsonb, '[{"word":"embassy","cn":"大使馆"},{"word":"budget","cn":"预算"},{"word":"currency","cn":"货币"}]'::jsonb, 2, 'required2', 'U5', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'Different Ways to Travel', 'Not everyone travels for the same reason, and today there are many different kinds of tourism. Food tourists choose a place mainly for its meals; some will cross a continent just to taste one famous local dish. Cultural tourists are drawn to theatres, galleries, museums and festivals, where they can learn about the art, history and lifestyle of a region. Adventure tourists are different again. They head for unusual or remote places and often engage in risky activities, such as climbing near a volcano or hiking deep into a forest. Whatever kind of traveller you happen to be, a simple map can make a new place much easier to enjoy. An online map on your phone is convenient, but it is almost useless without a signal. For that reason, a paper map from your hotel or the local tourist office is still well worth carrying. Mark your destination on it and draw a clear arrow to show your route.', '说明·旅游的种类与地图的用处', 159, '[{"q":"What do food tourists care about most?","answer":"C","options":["The museums and old festivals there.","Climbing near a dangerous volcano.","The meals that a place is known for.","Saving money on flights and hotels."],"explanation":"原文说美食游客主要为当地餐食而选目的地,选转述项。"},{"q":"What is one weakness of a phone map?","answer":"D","options":["It is far too heavy to carry around.","It cannot show any destination at all.","It is more expensive than a paper map.","It hardly works when there is no signal."],"explanation":"原文说手机地图没信号时几乎没用,选转述项。"},{"q":"What does the writer suggest doing with a paper map?","answer":"A","options":["Mark where you are going and show the way.","Throw it away once you reach the hotel.","Use it only inside the tourist office.","Give it to an adventure tour guide."],"explanation":"原文建议标出目的地并画箭头指明路线,选转述项。"}]'::jsonb, '[{"word":"tourism","cn":"旅游业"},{"word":"engage","cn":"参与"},{"word":"remote","cn":"偏远的"}]'::jsonb, 2, 'required2', 'U5', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'A Postcard from Yunnan', 'Alice was having a wonderful time in Yunnan, in the south-west of China, and she wanted to share it, so she sent a postcard to her friend Emma far away in Australia. At the moment she wrote, she was standing at the foot of the Yulong Snow Mountain. She and her group had spent the whole day hiking, and she had even seen some huge yaks along the path. The landscape, she wrote, was so lovely that no photograph could really capture it. The next day they planned to explore the old town of Lijiang, and Alice was praying for fine weather, sure that it would be great fun. A postcard may seem old-fashioned in the age of phones, yet there is something special about holding a card that has travelled thousands of kilometres. It carries not only a few lines of news but also a small piece of the very place where the writer has been.', '记叙·旅途中的一张明信片', 157, '[{"q":"Where was Alice when she wrote the postcard?","answer":"B","options":["Inside an old town in Australia.","At the foot of a snow mountain.","On a train crossing Europe.","At an airport waiting for a flight."],"explanation":"原文说她当时站在玉龙雪山脚下,选转述项。"},{"q":"What did Alice plan to do the next day?","answer":"C","options":["Climb to the top of the snow mountain.","Fly straight back home to Australia.","Explore Lijiang''s famous old town.","Spend another whole day with the yaks."],"explanation":"原文说她次日打算游览丽江古城,选转述项。"},{"q":"Why does the writer think a postcard is special?","answer":"D","options":["It is faster than sending a phone message.","It can never get lost in the post.","It costs nothing at all to send.","It brings a little of a faraway place to you."],"explanation":"原文说明信片带来远方一小片地方的感觉,选转述项。"}]'::jsonb, '[{"word":"landscape","cn":"风景"},{"word":"hike","cn":"徒步"},{"word":"explore","cn":"探索"}]'::jsonb, 2, 'required2', 'U5', 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required2', 'U5', 'My First Trip Alone', 'Last summer I went on my first trip (1)____, without my parents. I had saved enough money and made a careful (2)____ so that I would not spend too much. Before I left, I booked cheap (3)____ in a small hotel near the station. My flight left early, so I packed my (4)____ the night before and went to bed. At the airport I had to (5)____ some money into the local currency. When I arrived, a kind driver took me to my (6)____ along a busy road. The city was bigger than I had (7)____, and at first I felt a little lost. But I bought a paper (8)____ and marked my hotel on it. Slowly I learned to find my (9)____ around the streets. By the end of the week I felt much more (10)____, and I could not wait to plan my next journey.', 147, 2, '[{"q":"1","answer":"A","options":["abroad","ahead","inside","home"],"explanation":"first trip abroad 第一次出国旅行,副词。"},{"q":"2","answer":"B","options":["mistake","budget","promise","noise"],"explanation":"made a careful budget 做了仔细的预算。"},{"q":"3","answer":"C","options":["weather","homework","accommodation","traffic"],"explanation":"booked cheap accommodation 订了便宜的住宿。"},{"q":"4","answer":"D","options":["dinner","garden","lesson","luggage"],"explanation":"packed my luggage 收拾行李。"},{"q":"5","answer":"A","options":["change","throw","cook","sing"],"explanation":"change money into the local currency 把钱换成当地货币。"},{"q":"6","answer":"B","options":["kitchen","hotel","library","farm"],"explanation":"took me to my hotel 把我送到酒店。"},{"q":"7","answer":"C","options":["eaten","slept","expected","driven"],"explanation":"bigger than I had expected 比我预想的大。"},{"q":"8","answer":"D","options":["ticket","key","coat","map"],"explanation":"a paper map 一张纸质地图。"},{"q":"9","answer":"A","options":["way","name","age","size"],"explanation":"find my way around 找到方向。"},{"q":"10","answer":"B","options":["hungry","confident","sleepy","angry"],"explanation":"felt much more confident 感觉更自信。"}]'::jsonb, 1, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required2', 'U5', 'A Bike Ride Along the River', 'One spring morning my friend and I set off on a long bike (1)____ along the river. The (2)____ was perfect: warm sun and a gentle wind. We followed a quiet (3)____ that ran beside the water, far from the noisy main road. Tall trees lined both (4)____, and we could hear birds singing everywhere. After two hours we stopped to (5)____ a short rest and eat our sandwiches. The (6)____ along the river was so beautiful that we took dozens of photos. In the afternoon the path became (7)____, and we had to push our bikes up a steep hill. We were tired, but the view from the top was an amazing (8)____. On the way back, dark clouds began to (9)____, so we rode faster to reach home before the rain. It had been a simple but (10)____ day that we would never forget.', 146, 2, '[{"q":"1","answer":"C","options":["meal","song","ride","test"],"explanation":"a long bike ride 一段长途骑行。"},{"q":"2","answer":"D","options":["homework","market","lesson","weather"],"explanation":"The weather was perfect 天气很好。"},{"q":"3","answer":"A","options":["path","kitchen","ticket","coat"],"explanation":"a quiet path 一条安静的小路。"},{"q":"4","answer":"B","options":["hours","sides","prices","names"],"explanation":"lined both sides 排在两侧。"},{"q":"5","answer":"C","options":["throw","sell","take","lose"],"explanation":"take a short rest 短暂休息。"},{"q":"6","answer":"D","options":["traffic","noise","danger","scenery"],"explanation":"The scenery was beautiful 风景很美。"},{"q":"7","answer":"A","options":["harder","softer","cheaper","quieter"],"explanation":"the path became harder 路变得更难走。"},{"q":"8","answer":"B","options":["sound","sight","smell","taste"],"explanation":"an amazing sight 令人惊叹的景象。"},{"q":"9","answer":"C","options":["sing","sleep","appear","cook"],"explanation":"dark clouds began to appear 乌云开始出现。"},{"q":"10","answer":"D","options":["boring","terrible","dangerous","wonderful"],"explanation":"a simple but wonderful day 简单而美好的一天。"}]'::jsonb, 2, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required2', 'U5', 'Lost in a New City', 'On my second day in the city, I decided to (1)____ the old town on my own. Everything looked new and (2)____, and soon I had no idea where I was. I took out my phone to check the map, but there was no (3)____, so it was useless. For a moment I felt a little (4)____, standing alone among strangers. Then I remembered the advice in my guidebook: when you are lost, (5)____ someone for help. I walked up to a friendly shopkeeper and asked her the (6)____ to my hotel. She did not speak much English, but she drew a simple (7)____ on a piece of paper. Following her arrow, I turned left at the church and walked straight (8)____. Ten minutes later I could see the (9)____ sign of my hotel ahead. I felt so (10)____ that I had not given up. Getting lost had become part of the adventure.', 153, 2, '[{"q":"1","answer":"A","options":["explore","cook","clean","sell"],"explanation":"explore the old town 探索老城。"},{"q":"2","answer":"B","options":["boring","confusing","cheap","quiet"],"explanation":"looked new and confusing 看起来陌生又令人困惑。"},{"q":"3","answer":"C","options":["garden","ticket","signal","lesson"],"explanation":"there was no signal 没有信号。"},{"q":"4","answer":"D","options":["hungry","sleepy","proud","worried"],"explanation":"felt a little worried 感到有点担心。"},{"q":"5","answer":"A","options":["ask","throw","paint","drive"],"explanation":"ask someone for help 向别人求助。"},{"q":"6","answer":"B","options":["price","way","name","size"],"explanation":"asked her the way 向她问路。"},{"q":"7","answer":"C","options":["song","meal","map","coat"],"explanation":"drew a simple map 画了一张简单的地图。"},{"q":"8","answer":"D","options":["abroad","indoors","upstairs","ahead"],"explanation":"walked straight ahead 一直往前走。"},{"q":"9","answer":"A","options":["bright","heavy","empty","silent"],"explanation":"the bright sign 明亮的招牌。"},{"q":"10","answer":"B","options":["angry","glad","tired","bored"],"explanation":"felt so glad 感到很高兴。"}]'::jsonb, 3, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required2', 'U5', 'Why I Love Train Travel', 'Of all the ways to travel, I love going by (1)____ best of all. Unlike a plane, a train lets you watch the (2)____ change slowly outside your window. You pass green fields, quiet villages and rivers (3)____ through deep valleys. There is no need to (4)____ about traffic jams or parking. You can read a book, enjoy a hot drink, or simply (5)____ out of the window for hours. Trains are also kinder to the (6)____ than cars or planes, because they use less fuel for each traveller. Best of all, the (7)____ itself becomes part of the holiday, not just a boring wait. Last year I took a slow train across the (8)____, and I still remember every view. When the sun was (9)____ behind the hills, the whole sky turned gold. For me, a train window is the best (10)____ in the world.', 146, 2, '[{"q":"1","answer":"C","options":["plane","car","train","ship"],"explanation":"going by train 坐火车;下文 ''Unlike a plane, a train...'' 确认。"},{"q":"2","answer":"D","options":["weather","price","noise","scenery"],"explanation":"watch the scenery change 看风景变化。"},{"q":"3","answer":"A","options":["winding","sleeping","cooking","singing"],"explanation":"rivers winding through valleys 蜿蜒流过山谷的河,-ing 作后置定语。"},{"q":"4","answer":"B","options":["sing","worry","pay","cook"],"explanation":"no need to worry about traffic 不必担心交通。"},{"q":"5","answer":"C","options":["jump","cook","look","drive"],"explanation":"look out of the window 望向窗外。"},{"q":"6","answer":"D","options":["kitchen","library","market","environment"],"explanation":"kinder to the environment 对环境更友好。"},{"q":"7","answer":"A","options":["journey","ticket","station","engine"],"explanation":"the journey itself 旅程本身。"},{"q":"8","answer":"B","options":["table","country","garden","room"],"explanation":"a slow train across the country 慢车穿越全国。"},{"q":"9","answer":"C","options":["eating","reading","setting","talking"],"explanation":"the sun was setting 太阳正在西沉,-ing 表进行。"},{"q":"10","answer":"D","options":["meal","price","noise","seat"],"explanation":"the best seat in the world 世上最好的座位。"}]'::jsonb, 4, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required2', 'U5', 'A Night Under the Stars', 'Last autumn our class went camping near a quiet forest (1)____. We put up our tents before dark and then (2)____ a small fire to keep warm. As the sun was setting, the (3)____ around the lake turned a deep gold. We cooked a simple (4)____ over the fire and shared stories about our trips. When night came, there was no city light to (5)____ the view, so we could see thousands of (6)____ above us. It was the most (7)____ sight any of us had ever seen. Later, lying in our warm sleeping bags, we listened to the (8)____ wind moving through the trees. None of us felt (9)____, because we were all together. The next morning we woke early, packed our (10)____, and walked back to the bus, tired but very happy.', 134, 2, '[{"q":"1","answer":"A","options":["lake","kitchen","station","market"],"explanation":"a quiet forest lake 安静的林中湖。"},{"q":"2","answer":"B","options":["sold","built","cleaned","drove"],"explanation":"built a small fire 生了一小堆火。"},{"q":"3","answer":"C","options":["traffic","homework","scenery","price"],"explanation":"the scenery turned gold 景色变成金色。"},{"q":"4","answer":"D","options":["lesson","ticket","coat","meal"],"explanation":"cooked a simple meal 做了简单的一餐。"},{"q":"5","answer":"A","options":["spoil","sing","cook","sell"],"explanation":"no city light to spoil the view 没有城市灯光破坏视野。"},{"q":"6","answer":"B","options":["cars","stars","shops","roads"],"explanation":"thousands of stars 成千上万颗星星。"},{"q":"7","answer":"C","options":["boring","ugly","amazing","ordinary"],"explanation":"the most amazing sight 最令人惊叹的景象。"},{"q":"8","answer":"D","options":["heavy","bright","empty","gentle"],"explanation":"the gentle wind 轻柔的风。"},{"q":"9","answer":"A","options":["afraid","hungry","hot","proud"],"explanation":"none of us felt afraid 我们都不害怕。"},{"q":"10","answer":"B","options":["songs","bags","lessons","prices"],"explanation":"packed our bags 收拾好行李。"}]'::jsonb, 5, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required2', 'U5', 'A Homestay Abroad', 'Two years ago I spent a month living with a family (1)____, in a small town in France. At first I was nervous, because I could hardly (2)____ the language. My host family was very (3)____, though, and they helped me feel at home. Every morning I walked to a language school along a narrow (4)____ lined with old houses. In the afternoons my host mother often took me to (5)____ the town: the market, the church and the little art (6)____ near the river. Slowly my French got better, and I began to (7)____ the local way of life. I learned to cook a few local (8)____ and even made some new (9)____. When the month ended, saying goodbye was really (10)____. That homestay taught me that travel is not only about places, but also about people.', 138, 2, '[{"q":"1","answer":"C","options":["indoors","downstairs","abroad","nearby"],"explanation":"living with a family abroad 在国外寄宿。"},{"q":"2","answer":"D","options":["cook","drive","paint","speak"],"explanation":"could hardly speak the language 几乎不会说当地语言。"},{"q":"3","answer":"A","options":["kind","rude","lazy","silent"],"explanation":"my host family was very kind 寄宿家庭非常友善。"},{"q":"4","answer":"B","options":["kitchen","street","ticket","lesson"],"explanation":"a narrow street 一条狭窄的街道。"},{"q":"5","answer":"C","options":["sell","wash","explore","drive"],"explanation":"took me to explore the town 带我去逛这座小镇。"},{"q":"6","answer":"D","options":["kitchen","garden","station","gallery"],"explanation":"the little art gallery 小小的美术馆。"},{"q":"7","answer":"A","options":["enjoy","lose","waste","fear"],"explanation":"began to enjoy the local way of life 开始享受当地生活。"},{"q":"8","answer":"B","options":["songs","dishes","lessons","tickets"],"explanation":"cook a few local dishes 做几道当地菜。"},{"q":"9","answer":"C","options":["mistakes","noises","friends","rules"],"explanation":"made some new friends 结交了新朋友。"},{"q":"10","answer":"D","options":["easy","funny","cheap","hard"],"explanation":"saying goodbye was really hard 道别真的很难。"}]'::jsonb, 6, 'fltrp');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U5 听力·对话 At the Train Station', '外研社版必修第二册 U5 · dialogue', 3, 'Clerk: Good morning. Where would you like to go today?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U5 听力·独白 A Tip on Packing Light', '外研社版必修第二册 U5 · passage', 2, 'Here is a useful tip for anyone going on a trip. Try to travel light and pack only what you really need. A heavy bag is tiring to carry, and many airlines charge extra for large luggage. Before you leave, make a short list and lay everything on the bed. Then remove at least a third of it. Remember that you can buy most things at your destination if you forget them. Most importantly, leave some space in your bag for the souvenirs you will surely bring home.', '给出门旅行者的小贴士:尽量轻装,只带真正需要的东西;沉重的包背着累,很多航空公司对大件行李还要加收费用;出发前列个清单、把东西摊在床上,再拿掉至少三分之一;忘带的东西大多可在目的地买到;最重要的是,在包里留点空间装带回家的纪念品。', 'uk_male', '[{"q":"What is the tip mainly about?","type":"choice","answer":"D","options":["Choosing the cheapest flight.","Finding a good hotel.","Learning a foreign language.","Packing light and taking less."]},{"q":"Why can a heavy bag be a problem?","type":"choice","answer":"A","options":["It is tiring and may cost extra.","It is easy to lose at sea.","It cannot hold any clothes.","It is not allowed on trains."]},{"q":"What should you do after making a list?","type":"choice","answer":"B","options":["Add a third more things.","Remove about a third of the things.","Throw the list away.","Buy a bigger bag at once."]},{"q":"What can you do if you forget something?","type":"choice","answer":"C","options":["Cancel the whole trip.","Borrow it from the airline.","Buy it at your destination.","Go straight back home."]},{"q":"Why leave some space in the bag?","type":"choice","answer":"D","options":["For a heavy winter coat.","For another person''s things.","For a paper map and tickets.","For souvenirs to bring home."]}]'::jsonb, '[]'::jsonb, 'short', 'required2', 'U5', 'fltrp');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U5 听力·对话 Planning a Weekend Trip', '外研社版必修第二册 U5 · dialogue', 3, 'Anna: Do you have any plans for the long weekend?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U5 听力·独白 A Tour Guide''s Welcome', '外研社版必修第二册 U5 · passage', 2, 'Good morning, everyone, and welcome to our city tour. My name is Tom, and I''ll be your guide today. Our first stop is the old town, where you can see buildings that are hundreds of years old. After that, we''ll visit the art gallery by the river and stop for lunch at a local restaurant. In the afternoon, those who feel energetic can climb the hill for a wonderful view of the whole bay. Please stay close to the group and keep your maps with you. If you have any questions at any time, just ask me.', '导游 Tom 欢迎大家参加城市游;第一站是老城,可看到几百年历史的建筑;之后参观河边的美术馆,并在当地餐馆吃午饭;下午有体力的人可爬山,饱览整个海湾的美景;请大家紧跟队伍、带好地图;有问题随时问他。', 'uk_male', '[{"q":"What is Tom''s job?","type":"choice","answer":"B","options":["He is a bus driver.","He is a tour guide.","He is a hotel manager.","He is a photographer."]},{"q":"What is the first stop of the tour?","type":"choice","answer":"C","options":["The art gallery.","A local restaurant.","The old town.","The top of the hill."]},{"q":"What stands by the river?","type":"choice","answer":"D","options":["A train station.","A snow mountain.","A football field.","An art gallery."]},{"q":"What can energetic visitors do in the afternoon?","type":"choice","answer":"A","options":["Climb the hill for a view of the bay.","Swim across the river.","Drive to another city.","Take a long ferry trip."]},{"q":"What does Tom ask the visitors to do?","type":"choice","answer":"B","options":["Leave their bags on the bus.","Stay close and keep their maps.","Walk on their own all day.","Buy tickets at the gallery."]}]'::jsonb, '[]'::jsonb, 'short', 'required2', 'U5', 'fltrp');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U5 听力·对话 Checking in at the Hotel', '外研社版必修第二册 U5 · dialogue', 3, 'Receptionist: Good evening, and welcome to the Lakeside Hotel. Do you have a booking?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U5 听力·独白 A Quiet Island to Visit', '外研社版必修第二册 U5 · passage', 2, 'On today''s travel programme, we visit a small island that few tourists know about. To get there, you take a slow ferry that crosses the calm blue sea in about an hour. The island has no cars at all, so people walk or ride bikes everywhere. Its greatest treasure is its quiet beaches and the clear water around them. In the evening, with no city lights, the sky fills with thousands of stars. If you are looking for a remote place to relax and get back to nature, this peaceful island may be exactly what you need.', '今天的旅行节目带我们去一座鲜为人知的小岛;乘慢船约一小时穿过平静的蓝色海面即可到达;岛上完全没有汽车,人们靠步行或骑车出行;最大的财富是安静的海滩和周围清澈的海水;傍晚没有城市灯光,天空布满繁星;如果你想找个偏远之地放松、回归自然,这座宁静的小岛或许正合适。', 'uk_male', '[{"q":"How do visitors reach the island?","type":"choice","answer":"D","options":["By a fast plane.","By a long train.","By a private car.","By a slow ferry."]},{"q":"How long does the crossing take?","type":"choice","answer":"A","options":["About an hour.","About five minutes.","Half a day.","Two whole days."]},{"q":"How do people get around the island?","type":"choice","answer":"B","options":["By taxi and bus.","On foot or by bike.","By boat only.","By motorbike."]},{"q":"Why is the night sky so full of stars?","type":"choice","answer":"C","options":["The island is very high up.","It never rains there.","There are no city lights.","The moon is always bright."]},{"q":"What kind of traveller would enjoy the island?","type":"choice","answer":"D","options":["Someone who loves big busy cities.","Someone looking for fancy shops.","Someone who hates the sea.","Someone wanting a quiet, remote place."]}]'::jsonb, '[]'::jsonb, 'short', 'required2', 'U5', 'fltrp');
INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit, publisher) VALUES (10, 'Write a Postcard from a Trip(写一张旅行明信片)', 'A Postcard to a Friend', '假设你叫李华,正在外地旅行。请用英语给你的朋友 Sam 写一张约80词的明信片,内容包括:① 你现在在哪里、那里的风景或天气怎样;② 你到目前为止做了什么、印象最深的一件事;③ 接下来打算做什么。注意:适当使用 -ing 分词作定语(如 the rising sun, a path leading to the beach),语言地道连贯。', 'Suppose you are Li Hua, travelling away from home. Write a postcard (about 80 words) to your friend Sam, including: 1) where you are now and what the scenery or weather is like; 2) what you have done so far and the moment that impressed you most; 3) what you plan to do next. Try to use -ing participles as attributives (e.g. the rising sun, a path leading to the beach).', '["说明地点与风景/天气(I''m now in… / The scenery here is…)","已做的事 + 印象最深的瞬间(So far I''ve… / The best moment was…)","下一步计划(Tomorrow we''re going to…)","用 -ing 分词作定语,语言连贯"]'::jsonb, 70, 100, 'Dear Sam, Greetings from the seaside town of Brighton! I''m sitting on a beach now, watching the setting sun turn the sky pink. So far I''ve walked along a quiet path leading to the harbour and taken hundreds of photos of the passing boats. The best moment was seeing a group of dolphins swimming close to the shore — amazing! Tomorrow we''re going to hike up the hill for a view of the whole bay. The scenery here is breathtaking. Wish you were here! Love, Li Hua', '【15 分制】A 档(13-15):五要素齐全、组织有条理、语言准确多样;B 档(10-12):要点较全、少量错误;C 档(7-9):要点偏少、句型简单;D 档(0-6):内容不完整、错误多。', '["I''m sitting on a beach, watching the setting sun turn the sky pink.","I''ve walked along a quiet path leading to the harbour.","I took hundreds of photos of the passing boats.","The best moment was seeing a group of dolphins swimming close to the shore."]'::jsonb, '[{"wrong":"a path led to the harbour","correct":"a path leading to the harbour","note":"后置定语表主动用 -ing 分词,不用过去式 led。"},{"wrong":"the setted sun","correct":"the setting sun","note":"太阳主动''西沉'',前置定语用 -ing,不用 -ed。"},{"wrong":"It was a very amazed view.","correct":"It was a very amazing view.","note":"事物令人惊叹用 -ing;人感到惊叹才用 -ed。"}]'::jsonb, '【旅行明信片结构】
INSERT INTO public.junior_grammar_tips (grade, volume, unit, content, publisher) VALUES (10, 'required2', 'U5', '{"title":"-ing 分词作定语速查","intro":"-ing 分词作定语表''主动 / 正在进行'':被修饰的名词主动发出这个动作。单个分词放名词前(the rising sun),带宾语或状语的分词短语放名词后(the road leading to town = the road that leads to town)。","table":{"headers":["位置 / 形式","用法 · 例句 · 等价"],"rows":[["前置(单个 -ing)","running water 流动的水;the changing seasons 变化的季节"],["后置(-ing 短语)","the road leading to town = the road that leads to town"],["-ing(主动·使人……)","an exciting journey 令人兴奋的旅程(旅程让人兴奋)"],["-ed(被动·人感到……)","an excited tourist 兴奋的游客(游客感到兴奋)"]]},"specialRules":[{"rule":"名词主动发出动作 / 正在进行 → 用 -ing","mark":"the passing cars(车主动驶过)"},{"rule":"分词带宾语或状语时,要放到名词之后","rule_alt":"the man standing there = who is standing there","mark":"= 定语从句"},{"rule":"事物''令人……''用 -ing;人''感到……''用 -ed","mark":"an amazing view / an amazed visitor"},{"rule":"-ing 表主动,-ed 表被动/完成,别混","mark":"running water √ / run water ×"}],"why":["-ing 分词等于一个主动的定语从句:the boy reading a book = the boy who is reading a book;名词与动作是主动关系,所以用 -ing 而不是 -ed。"],"gaokaoPoints":["语法填空 / 短文改错高频:看名词与动词是主动(-ing)还是被动(-ed)。","情绪类形容词:修饰''事/物''用 -ing,修饰''人/感受''用 -ed(exciting/excited, boring/bored)。","分词短语后置 = 省略''关系代词 + be''的定语从句:the train coming from Beijing = which is coming…"],"examVsReal":[{"exam":"the road leading to the town（考试/书面)","real":"the road that goes to town","note":"考试爱考分词后置;口语常直接用定语从句或介词短语"},{"exam":"an exciting trip（考试)","real":"a trip that was really fun / so much fun","note":"考试卡 -ing/-ed;口语里常换成 fun、great 等更口语的说法"}]}'::jsonb, 'fltrp');
